package net.kckern.portalkeys.payload;
import android.content.Context;import android.provider.Settings;import org.json.JSONObject;
final class SettingsOps{
    static JSONObject get(Context c,String ns,String key){JSONObject o=new JSONObject();try{String v=ns.equals("global")?Settings.Global.getString(c.getContentResolver(),key):ns.equals("system")?Settings.System.getString(c.getContentResolver(),key):Settings.Secure.getString(c.getContentResolver(),key);return o.put("ok",true).put("value",v==null?JSONObject.NULL:v);}catch(Exception e){try{return o.put("ok",false).put("error",e.toString());}catch(Exception ignored){return o;}}}
    static JSONObject put(Context c,String ns,String key,String value){JSONObject o=new JSONObject();try{boolean ok=ns.equals("global")?Settings.Global.putString(c.getContentResolver(),key,value):ns.equals("system")?Settings.System.putString(c.getContentResolver(),key,value):Settings.Secure.putString(c.getContentResolver(),key,value);return o.put("ok",ok);}catch(Exception e){try{return o.put("ok",false).put("error",e.toString());}catch(Exception ignored){return o;}}}
    static JSONObject enableA11y(Context c){String component="net.kckern.portalkeys/net.kckern.portalkeys.PortalKeysService";try{String cur=Settings.Secure.getString(c.getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);if(cur==null||cur.isEmpty())cur=component;else if(!java.util.Arrays.asList(cur.split(":")).contains(component))cur+=":"+component;Settings.Secure.putString(c.getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES,cur);Settings.Secure.putInt(c.getContentResolver(),Settings.Secure.ACCESSIBILITY_ENABLED,1);return new JSONObject().put("ok",true).put("component",component);}catch(Exception e){try{return new JSONObject().put("ok",false).put("error",e.toString());}catch(Exception ignored){return new JSONObject();}}}
}
